import { Category, ErrorEvent, Identity, PartyIdentification, SearchEvent } from '../events';
/**
Description: A product search is performed.
*/
export type Search = {
    events: Array<SearchEvent | Identity | PartyIdentification | ErrorEvent>;
}

export class SearchBuilder {

    private search: Search = {
        events: []
    }

    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;
    private searchEvent!: SearchEvent;

    public withErrorEvent(errorEvent: ErrorEvent) : SearchBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : SearchBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : SearchBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }
    public withSearchEvent(searchEvent: SearchEvent) : SearchBuilder {
        this.searchEvent = searchEvent;
        return this;
    }

    public build() : Search {
        if(this.errorEvent) {
            this.search.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.search.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.search.events.push(this.partyIdentification);
        }
        if(this.searchEvent) {
            this.search.events.push(this.searchEvent);
        }

        return this.search;
    }
}
